input.sparql:
SELECT ?eqName ?ts WHERE {
  ?sens a brick:PowerSensor ; brick:hasInput ?eq .
  ?eq rdfs:label ?eqName .
  ?sens ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT ?eqUri ?eqName ?sensLabel WHERE {
  ?s a brick:Electric_Power_Sensor ; rdfs:label ?sensLabel ; brick:isPointOf ?eq .
  OPTIONAL { ?eq rdfs:label ?eqName . }
}

SELECT ?eq ?eqName ?eqClass ?sensLabel WHERE {
  ?s a brick:Electric_Power_Sensor ; rdfs:label ?sensLabel ; brick:isPointOf ?eq .
  ?eq a ?eqClass .
  OPTIONAL { ?eq rdfs:label ?eqName . }
}
